PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(organization_id,email));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS storm_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, status TEXT NOT NULL, severity TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, opened_at TEXT NOT NULL, closed_at TEXT);
CREATE TABLE IF NOT EXISTS forecast_versions (id TEXT PRIMARY KEY, storm_id TEXT NOT NULL REFERENCES storm_events(id), version INTEGER NOT NULL, source TEXT NOT NULL, wind_kph REAL NOT NULL, warning_level TEXT NOT NULL, valid_until TEXT NOT NULL, published_at TEXT NOT NULL, UNIQUE(storm_id,version));
CREATE TABLE IF NOT EXISTS risk_zones (id TEXT PRIMARY KEY, storm_id TEXT NOT NULL REFERENCES storm_events(id), name TEXT NOT NULL, risk_level TEXT NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0, UNIQUE(storm_id,name));
CREATE TABLE IF NOT EXISTS shelters (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, address TEXT NOT NULL, status TEXT NOT NULL, capacity INTEGER NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS shelter_reservations (id TEXT PRIMARY KEY, shelter_id TEXT NOT NULL REFERENCES shelters(id), household_id TEXT NOT NULL, people INTEGER NOT NULL, status TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(shelter_id,household_id));
CREATE TABLE IF NOT EXISTS evacuation_orders (id TEXT PRIMARY KEY, storm_id TEXT NOT NULL REFERENCES storm_events(id), zone_id TEXT NOT NULL REFERENCES risk_zones(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, published_at TEXT, cancelled_at TEXT, UNIQUE(storm_id,zone_id));
CREATE TABLE IF NOT EXISTS households (id TEXT PRIMARY KEY, zone_id TEXT NOT NULL REFERENCES risk_zones(id), head_name TEXT NOT NULL, people INTEGER NOT NULL, status TEXT NOT NULL, shelter_id TEXT, confirmed_at TEXT);
CREATE TABLE IF NOT EXISTS dispatch_tasks (id TEXT PRIMARY KEY, storm_id TEXT NOT NULL REFERENCES storm_events(id), zone_id TEXT REFERENCES risk_zones(id), title TEXT NOT NULL, status TEXT NOT NULL, priority INTEGER NOT NULL, owner_id TEXT, lease_until TEXT, version INTEGER NOT NULL DEFAULT 1, report TEXT, created_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS supply_items (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), sku TEXT NOT NULL, name TEXT NOT NULL, quantity INTEGER NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, UNIQUE(organization_id,sku));
CREATE TABLE IF NOT EXISTS supply_movements (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES supply_items(id), storm_id TEXT NOT NULL REFERENCES storm_events(id), from_org_id TEXT NOT NULL REFERENCES organizations(id), shelter_id TEXT NOT NULL REFERENCES shelters(id), quantity INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, storm_id TEXT NOT NULL REFERENCES storm_events(id), order_id TEXT REFERENCES evacuation_orders(id), channel TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS outbox_events (id TEXT PRIMARY KEY, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, event_type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, lease_owner TEXT, lease_until TEXT, last_error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), actor_id TEXT, object_type TEXT NOT NULL, object_id TEXT NOT NULL, action TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_records (organization_id TEXT NOT NULL, method TEXT NOT NULL, path TEXT NOT NULL, key TEXT NOT NULL, response_code INTEGER NOT NULL, response_body TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, PRIMARY KEY(organization_id,method,path,key));
CREATE INDEX IF NOT EXISTS idx_forecasts_storm_version ON forecast_versions(storm_id,version);
CREATE INDEX IF NOT EXISTS idx_zones_storm_risk ON risk_zones(storm_id,risk_level,confirmed);
CREATE INDEX IF NOT EXISTS idx_shelters_status ON shelters(status,version);
CREATE INDEX IF NOT EXISTS idx_dispatch_due ON dispatch_tasks(status,lease_until,priority);
CREATE INDEX IF NOT EXISTS idx_outbox_due ON outbox_events(status,available_at);
CREATE INDEX IF NOT EXISTS idx_audit_object ON audit_events(object_type,object_id,created_at);
